/* Blackline CAD2D — elevation collection from user-provided Olimpiadas DXF,
 * plus original editable high-detail window elevations.
 * Objects are individual native vector definitions, not images/screenshots.
 * Source sizes are nominal insertion dimensions; no certified manufacturer dimensions.
 * No ROCA/FERRUM/manufacturer blocks. Existing and hidden blocks are untouched.
 */
(function(){'use strict';
const LIB=window.CAD2D_ARQ_LIBRARY;
if(!LIB||!LIB.Builder||!Array.isArray(LIB.library))return;
const rows=[["ca_puerta_elev41","Puerta doble de tableros · alzado","Alzados",1.9,2.1112,""],["ca_puerta_elev38","Puerta doble clásica · alzado","Alzados",1.9,2.1112,""],["ca_puerta_elev35","Puerta de cuarterones múltiples · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev17","Puerta de ocho paneles · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev27","Puerta de tres tableros · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev30","Puerta de paneles biselados · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev09","Puerta vidriada con retícula · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev36","Puerta con celosía diagonal · alzado","Alzados",0.95,2.1111,""],["ca_puerta_elev39","Puerta doble geométrica · alzado","Alzados",1.9,2.1112,""],["ca_puerta_elev14","Puerta de cuatro tableros · alzado","Alzados",0.95,2.1111,""],["ca_co_refr02","Heladera con tirador · vista frontal","Mobiliario en vista",0.7,1.4506,""],["ca_co_refr06","Heladera de dos hojas · vista frontal","Mobiliario en vista",0.7,1.7782,"BU602wVOVVUEerTbBHpVVQAAchz//3IcBU602wBgtNsFTlVVAGBVVQAAYQv//2ELAAAREf//EREAAMEW///BFgpoVVUEelVVCmi02wR6tNsAAP//AAAAAP///////wAAAGD//wBgchwKaP//CmhyHAAAAACtFQAAAACwBf//sAUAAP///////1LqsAVS6gAArRWwBa0VAABS6gAA//8AAA=="],["ca_co_refr17","Heladera ventilada · vista frontal","Mobiliario en vista",1.25,1.4583,""]];
const ids=new Set(LIB.library.map(x=>x.id));
let doors=0,fridges=0,windows=0;
for(const [source,name,cat,w,d,data] of rows){
 const id='olymp2-'+source.replace(/[^a-z0-9]+/g,'-');
 if(ids.has(id))continue;
 const raw=atob(data);
 if(!raw.length||raw.length%8)continue;
 const door=/^ca_puerta_elev/.test(source);
 LIB.library.push({id,source,name,cat,w,d,
  family:door?'Puertas en vista':'Heladeras en vista',
  originalDXF:true,nominalDimensions:true,paidOnly:false,pro:false,
  author:'Colección Olimpiadas · dibujos originales aportados por el usuario',
  wMin:door?w*.75:w,wMax:door?w*1.35:w,
  dMin:door?d*.9:d,dMax:door?d*1.12:d,lockAspect:false,
  gen(b,W,D){for(let i=0;i<raw.length;i+=8){const n=j=>raw.charCodeAt(i+j)+(raw.charCodeAt(i+j+1)<<8);
    b.line(n(0)/65535*W,n(2)/65535*D,n(4)/65535*W,n(6)/65535*D);
  }}
 });
 ids.add(id);if(door)doors++;else fridges++;
 if(Array.isArray(LIB.categories)&&!LIB.categories.includes(cat))LIB.categories.push(cat);
}
// Window elevations authored directly for Blackline (accurate frame/sash structure),
// deliberately more detailed than the low-quality sketches hidden in 2026 cleanup.
function addWindow(id,name,w,h,kind){
 if(ids.has(id))return;
 const m=(b,W,H)=>{
  const t=Math.min(.066,W*.052,H*.052),g=t*.22;
  const rect=(x,y,ww,hh)=>{if(ww>1e-4&&hh>1e-4)b.rect(x,y,ww,hh)};
  const line=(x,y,x2,y2,o)=>b.line(x,y,x2,y2,o);
  const sash=(x,y,ww,hh,op)=>{
   const k=Math.min(t*.78,ww*.075,hh*.085);
   rect(x,y,ww,hh);rect(x+k*.62,y+k*.62,ww-1.24*k,hh-1.24*k);
   rect(x+k*1.55,y+k*1.55,ww-3.10*k,hh-3.10*k);
   // Fine reflections represent glazing, not additional opaque panels.
   const x0=x+ww*.16,x1=x+ww*.35,y0=y+hh*.22,y1=y+hh*.76;
   line(x0,y0,x1,y1);line(x0+ww*.06,y0,x1+ww*.06,y1);
   if(op==='slider'){
    rect(x+ww*.88,y+hh*.43,ww*.035,hh*.14);
    line(x+ww*.905,y+hh*.46,x+ww*.905,y+hh*.54);
   }
   if(op==='pivot'){line(x+k*2,y+k*2,x+ww/2,y+hh/2,{dashed:true});
    line(x+ww-k*2,y+k*2,x+ww/2,y+hh/2,{dashed:true});}
  };
  // Outer frame: three line weights through nested extrusions.
  rect(0,0,W,H);rect(t*.36,t*.36,W-.72*t,H-.72*t);
  rect(t*1.20,t*1.20,W-2.4*t,H-2.4*t);
  line(0,-.025,W,-.025);line(.01,-.05,W-.01,-.05);line(t,-.025,t,-.05);
  line(W-t,-.025,W-t,-.05);
  const x=t*1.65,y=t*1.65,iw=W-3.3*t,ih=H-3.3*t;
  if(kind==='fixed'){sash(x,y,iw,ih,'fixed');}
  if(kind==='sliding2'){
   const split=x+iw/2,lap=t*.58;
   sash(x,y,iw/2+lap,ih,'slider');sash(split-lap,y,iw/2+lap,ih,'slider');
   line(x,y+t*.38,x+iw,y+t*.38);line(x,H-t*.58,x+iw,H-t*.58);
   rect(split-t*.54,y,t*1.08,ih);rect(split-t*.18,y,t*.36,ih);
  }
  if(kind==='sliding3'){
   const sw=iw/3,lap=t*.52;
   for(let j=0;j<3;j++)sash(x+sw*j-(j?lap:0),y,sw+(j?lap:0)+(j<2?lap:0),ih,'slider');
   for(let j=1;j<=2;j++){const p=x+sw*j;rect(p-t*.50,y,t,ih);line(p,y+t*.3,p,H-t*.3);}
   line(x,y+t*.36,x+iw,y+t*.36);line(x,H-t*.58,x+iw,H-t*.58);
  }
  if(kind==='transom'){
   const hh=ih*.28,part=y+ih-hh;
   sash(x,y,iw,ih-hh,'fixed');rect(x,part-t*.5,iw,t);
   sash(x,part,iw,hh,'pivot');line(x+iw/2,part+hh*.35,x+iw/2,part+hh*.83,{dashed:true});
  }
  if(kind==='casement'){
   const split=x+iw/2;
   sash(x,y,iw/2,ih,'pivot');sash(split,y,iw/2,ih,'pivot');
   rect(split-t*.55,y,t*1.1,ih);
   rect(split-t*1.2,y+ih*.49,t*.36,ih*.10);
   rect(split+t*.9,y+ih*.49,t*.36,ih*.10);
  }
 };
 LIB.library.push({id,name,cat:'Alzados',family:'Ventanas en vista',w,d:h,pro:false,paidOnly:false,
  originalCAD:true,author:'Blackline CAD · trazado arquitectónico propio',
  wMin:w*.65,wMax:w*2,dMin:h*.7,dMax:h*1.6,lockAspect:false,
  gen:m
 });ids.add(id);windows++;
}
[
 ['bl-view-window-fixed-120','Ventana fija · alzado técnico',1.2,1.4,'fixed'],
 ['bl-view-window-slider-180','Ventana corrediza de 2 hojas · alzado',1.8,1.4,'sliding2'],
 ['bl-view-window-slider-270','Ventanal corredizo de 3 hojas · alzado',2.7,1.6,'sliding3'],
 ['bl-view-window-transom-120','Ventana con banderola superior · alzado',1.2,1.55,'transom'],
 ['bl-view-window-casement-140','Ventana de dos hojas batientes · alzado',1.4,1.45,'casement']
].forEach(x=>addWindow(...x));
window.CAD2D_ELEVATION_RESCUE=Object.freeze({version:20261123,doors,windows,fridges,
 source:'Colección Olimpiadas usuario + ventanas Blackline originales',
 selectedIds:rows.map(r=>'olymp2-'+r[0].replace(/[^a-z0-9]+/g,'-')),
 customWindowIds:['bl-view-window-fixed-120','bl-view-window-slider-180','bl-view-window-slider-270','bl-view-window-transom-120','bl-view-window-casement-140']});
})();
